def countTopologicalOrders(n, edges):
    MOD = 1000000007
    pred = [0] * n
    for a, b in edges:
        pred[b] |= 1 << a
    full = (1 << n) - 1
    dp = [0] * (1 << n)
    dp[0] = 1
    for mask in range(1 << n):
        d = dp[mask]
        if not d:
            continue
        rest = full & ~mask
        while rest:
            low = rest & -rest
            v = low.bit_length() - 1
            if pred[v] & ~mask == 0:
                dp[mask | low] = (dp[mask | low] + d) % MOD
            rest ^= low
    return dp[full]
